11	/*!
12	 * \file resize_bilinear_v2_infershape.cpp
13	 * \brief resize_bilinear_v2_infershape
14	 */
15	
16	#include "register/op_impl_registry.h"
17	#include "log/log.h"
18	#include "util/shape_util.h"
19	#include "infershape_utils.h"
20	
21	using namespace ge;
22	namespace ops {
23	
24	struct OutInfo {
25	    int64_t output_h{0};
26	    int64_t output_w{0};
27	    int64_t output_d{0};
28	};
29	
30	static constexpr size_t IN_X = 0;
31	static constexpr size_t IN_SIZE = 1;
32	static constexpr size_t ATTR_2_IDX = 2;
33	static constexpr size_t OUT_Y = 0;
34	static constexpr size_t SIZE_NUM_2D = 2;
35	static const int64_t OUTPUT_DIM_NUM = 4;
36	
37	template <typename T>
38	static bool GetSizeValueFor2D(const gert::InferShapeContext* context, const gert::Tensor* size_tensor,
39	                              OutInfo& out_size)
40	{
41	    const T* size_value = size_tensor->GetData<T>();
42	    const size_t size_num = size_tensor->GetShapeSize();
43	    OP_CHECK_IF(size_num != SIZE_NUM_2D,
44	                OP_LOGE(context->GetNodeName(), "The size number must be 2, but is %d", size_num), return false);
45	
46	    out_size.output_h = static_cast<int64_t>(size_value[0]);
47	    out_size.output_w = static_cast<int64_t>(size_value[1]);
48	
49	    return true;
50	}
51	
52	static bool GetSizeFor2D(const gert::InferShapeContext* context, const gert::Tensor* size_tensor, OutInfo& out_size)
53	{
54	    if (!Ops::Cv::IsConstTensor(size_tensor)) {
55	        OP_LOGW(context->GetNodeName(), "the input is not const tensor, out_size will be -1.");
56	        out_size.output_h = ge::UNKNOWN_DIM;
57	        out_size.output_w = ge::UNKNOWN_DIM;
58	        return true;
59	    }
60	    ge::DataType size_dtype = size_tensor->GetDataType();
61	    switch (size_dtype) {
62	        case ge::DT_INT32: {
63	            OP_CHECK_IF(!GetSizeValueFor2D<int32_t>(context, size_tensor, out_size),
64	                        OP_LOGE(context->GetNodeName(), "Get size const for int32 failed!"), return false);
65	            break;
66	        }
67	        default:
68	            OP_LOGE_FOR_INVALID_DTYPE(context->GetNodeName(), "size", Ops::Base::ToString(size_dtype).c_str(), "int32");
69	            return false;
70	    }
71	    return true;
72	}
73	
74	static bool ResizeInfershapeFor2D(const gert::InferShapeContext* context, const gert::Shape* x_shape,
75	                                  const ge::Format input_format, const OutInfo& out_info, gert::Shape* y_shape)
76	{
77	    OP_LOGD(context->GetNodeName(), "Begin to do ResizeInfershape");
78	    OP_LOGD(context->GetNodeName(), "input x shape = %s", Ops::Base::ToString(*x_shape).c_str());
79	    OP_LOGD(context->GetNodeName(), "input x format = %s", Ops::Base::ToString(input_format).c_str());
80	    OP_CHECK_IF(input_format != FORMAT_NHWC && input_format != FORMAT_NCHW,
81	                OP_LOGE(context->GetNodeName(), "input format only support [NHWC,NCHW], but is %s",
82	                        Ops::Base::ToString(input_format).c_str()),
83	                return false);
84	
85	    // -2 infer shape
86	    if (Ops::Base::IsUnknownRank(*x_shape)) {
87	        OP_LOGD(context->GetNodeName(), "x_shape is UnknownRank, set output_shape to (-1, -1, -1, -1)");
88	        Ops::Base::SetUnknownShape(OUTPUT_DIM_NUM, *y_shape);
89	    } else {
90	        constexpr size_t output_len = OUTPUT_DIM_NUM;
91	        const size_t input_dim_size = x_shape->GetDimNum();
92	        OP_CHECK_IF(input_dim_size != output_len,
93	                    OP_LOGE(context->GetNodeName(), "input shape only support 4D, but is %s",
94	                            Ops::Base::ToString(*x_shape).c_str()),
95	                    return false);
96	
97	        *y_shape = *x_shape;
98	    }
99	
100	    const size_t image_h_idx = input_format == FORMAT_NHWC ? 1 : 2;
101	    const size_t image_w_idx = input_format == FORMAT_NHWC ? 2 : 3;
102	    y_shape->SetDim(image_h_idx, out_info.output_h);
103	    y_shape->SetDim(image_w_idx, out_info.output_w);
104	
105	    OP_LOGD(context->GetNodeName(), "output y = %s", Ops::Base::ToString(*y_shape).c_str());
106	    OP_LOGD(context->GetNodeName(), "End to do ResizeInfershape");
107	
108	    return true;
109	}
110	
111	ge::graphStatus InferShape4Resize2DWithConstSize(gert::InferShapeContext* context)
112	{
113	    OP_LOGD(context->GetNodeName(), "begin to do InferShape4Resize2DWithConstSize");
114	    const gert::Shape* x_shape = context->GetInputShape(IN_X);
115	    OP_CHECK_NULL_WITH_CONTEXT(context, x_shape);
116	    gert::Shape* y_shape = context->GetOutputShape(OUT_Y);
117	    OP_CHECK_NULL_WITH_CONTEXT(context, y_shape);
118	    const gert::Tensor* size_tensor = context->GetInputTensor(IN_SIZE);
119	    OP_CHECK_NULL_WITH_CONTEXT(context, size_tensor);
120	
121	    OutInfo out_size;
122	    OP_LOGD(context->GetNodeName(), "begin to get size from input %zu.", IN_SIZE);
123	    OP_CHECK_IF(!GetSizeFor2D(context, size_tensor, out_size),
124	                OP_LOGE(context->GetNodeName(), "Get size const failed!"), return ge::GRAPH_FAILED);
125	
126	    auto x_runtime_desc = context->GetInputDesc(IN_X);
127	    OP_CHECK_NULL_WITH_CONTEXT(context, x_runtime_desc);
128	    ge::Format input_format = x_runtime_desc->GetOriginFormat();
129	    OP_CHECK_IF(!ResizeInfershapeFor2D(context, x_shape, input_format, out_size, y_shape),
130	                OP_LOGE(context->GetNodeName(), "Do ResizeInfershape failed!"), return ge::GRAPH_FAILED);
131	
132	    OP_LOGD(context->GetNodeName(), "Do InferShape4Resize2DWithConstSize success");
133	
134	    return ge::GRAPH_SUCCESS;
135	}
136	
137	graphStatus InferDtype4ResizeBilinearV2(gert::InferDataTypeContext* context)
138	{
139	    OP_LOGD("ResizeBilinearV2", "InferDtype4ResizeBilinearV2 enter");
140	    if (context == nullptr) {
141	        OP_LOGE("ResizeBilinearV2", "InferDtype4ResizeBilinearV2 context is null.");
142	        return GRAPH_FAILED;
143	    }
144	
145	    OP_LOGI(context->GetNodeName(), "set output to default dtype float");
146	    context->SetOutputDataType(0, ge::DT_FLOAT);
147	    auto attrsPtr = context->GetAttrs();
148	    if (attrsPtr == nullptr) {
149	        OP_LOGI(context->GetNodeName(), "attrsPtr is nullptr");
150	        return GRAPH_SUCCESS;
151	    }
152	
153	    const int64_t* dstDtype = attrsPtr->GetAttrPointer<int64_t>(ATTR_2_IDX);
154	    if (dstDtype == nullptr) {
155	        OP_LOGI(context->GetNodeName(), "dstDtype is not configed");
156	        return GRAPH_SUCCESS;
157	    }
158	
159	    ge::DataType outDtype = static_cast<ge::DataType>(*dstDtype);
160	    OP_LOGD(context->GetNodeName(), "dtype in attrs is %ld", (int64_t)outDtype);
161	    OP_CHECK_IF(!(outDtype == ge::DT_FLOAT || outDtype == ge::DT_FLOAT16 || outDtype == ge::DT_BF16 ||
162	                  outDtype == ge::DT_UINT8),
163	                OP_LOGE(context->GetNodeName(), "dtype should be float32, float16, bfloat16 or uint8."),
164	                return GRAPH_FAILED);
165	    auto xDtype = context->GetInputDataType(0);
166	    OP_LOGD(context->GetNodeName(), "xDtype is %s", Ops::Base::ToString(xDtype).c_str());
167	
168	    OP_CHECK_IF((xDtype == ge::DT_FLOAT && (outDtype == ge::DT_FLOAT16 || outDtype == ge::DT_BF16)),
169	                OP_LOGE(context->GetNodeName(), "xDtype is float32, outDtype should not be float16 or bfloat16."),
170	                return GRAPH_FAILED);
171	    OP_CHECK_IF(
172	        ((xDtype == ge::DT_FLOAT16 && outDtype == ge::DT_BF16) ||
173	         (xDtype == ge::DT_BF16 && outDtype == ge::DT_FLOAT16)),
174	        OP_LOGE(context->GetNodeName(), "xDtype is float16 or bfloat16, outDtype should be same to xDtype or float32."),
175	        return GRAPH_FAILED);
176	
177	    OP_LOGI(context->GetNodeName(), "set output to configed dtype: %s", Ops::Base::ToString(outDtype).c_str());
178	    context->SetOutputDataType(0, outDtype);
179	    OP_LOGD(context->GetNodeName(), "Do InferDtype4ResizeBilinearV2 success");
180	    return GRAPH_SUCCESS;
181	}
182	
183	IMPL_OP_INFERSHAPE(ResizeBilinearV2)
184	    .InferShape(InferShape4Resize2DWithConstSize)
185	    .InputsDataDependency({IN_SIZE})
186	    .InferDataType(InferDtype4ResizeBilinearV2);
187	} // namespace ops
188

