    if (TILING_KEY_IS(TILING_KEY_SIMT_NCHW_IDX64)) {
        if (tilingData.halfPixelCenters > 0) {
            ResizeBilinearV2::ResizeBilinearV2SimtNCHW<DTYPE_X, DTYPE_Y, true, 0, uint64_t> op;
            op.Init(x, size, y, &tilingData);
            op.Process();
